mapper.select:
select o.order_id orderId, o.ctime, o.user_id user_id, u.mail, d.sku_id skuId, s.sku_name skuName, s.sku_category skuCategory, s.sku_type skuType, d.price, d.total_amt totalAmt, d.currency, d.sku_num skuNum
from buy_order o left join buy_order_detail d on o.order_id = d.order_id left join buy_user u on o.user_id = u.user_id left join buy_sku s on d.sku_id = s.sku_id where o.is_deleted = 0 and d.is_deleted = 0
and o.ctime >= #{startCtime} and o.ctime <= #{endCtime}
and s.classification in
#{item}
and s.status in
#{item}
order by o.ctime, o.order_id desc
